// v23.xx (gfx37), HIS ORDER 2026-10-12 (the graphics program, item 9 and the 60 fps answer, 21 b): THE FOG BANKS ARE BAKED. The seven
// drifting fog banks of v7.43 each built a new radial gradient every frame of a fog raid and filled a square up to 1,340 pixels across
// with it: seven gradient objects a frame for a soft shape that never changes. The shape is now painted once into one sprite
// (gfxFogBankSpr, kept in the store registry and remade after a lost context) and each bank is that sprite drawn at the same place,
// size and strength, so the fog looks the same and the frame makes no gradients for it. GFX.bypass keeps the old per-frame gradients.
function gfxFogBankSpr(){
  if(GFX.bypass) return null;
  var st=gfxStore('gfxE'), m=st.m, c, x, gr;
  if(m.fogbank) return m.fogbank;
  c=document.createElement('canvas'); c.width=c.height=256; x=c.getContext('2d');
  gr=x.createRadialGradient(128,128,128*0.15,128,128,128);
  gr.addColorStop(0,'rgba(205,214,226,1)'); gr.addColorStop(1,'rgba(205,214,226,0)');
  x.fillStyle=gr; x.fillRect(0,0,256,256); m.fogbank=c; st.n++;
  return c;
}
// ===== GFX-E end =====

var _fbs=null; try{ _fbs=gfxFogBankSpr(); }catch(_fbe){ _fbs=null; }   // v23.xx (gfx37): one baked bank sprite, same place, size and strength
if(_fbs){ wc.globalAlpha=Math.min(1,0.11*_fa); wc.drawImage(_fbs,_fx-_fr,_fy-_fr,_fr*2,_fr*2); wc.globalAlpha=1; continue; }
var _fgd=wc.createRadialGradient(_fx,_fy,_fr*0.15,_fx,_fy,_fr);
_fgd.addColorStop(0,'rgba(205,214,226,'+(0.11*_fa).toFixed(3)+')');
_fgd.addColorStop(1,'rgba(205,214,226,0)');
wc.fillStyle=_fgd;
wc.fillRect(_fx-_fr,_fy-_fr,_fr*2,_fr*2);

